create or replace function public.borrador_ia_json(d public.borradores_ia)returns jsonb language sql immutable set search_path=''as $$select jsonb_build_object('id',d.id,'encounterId',d.atencion_id,'patientId',d.paciente_id,'type',d.tipo,'status',d.estado,'content',d.contenido,'missingFields',d.campos_faltantes,'warning',d.advertencia,'rejectionReason',d.motivo_rechazo,'generatedBy',d.generado_por,'generatedAt',d.generado_en,'reviewedBy',d.revisado_por,'reviewedAt',d.revisado_en,'version',d.version)$$;
create or replace function public.listar_borradores_ia(atencion_id bigint)returns jsonb language plpgsql stable security definer set search_path=''as $$declare result jsonb;begin if not public.has_permission('IA_LEER')then raise exception using errcode='42501',message='No autorizado para consultar borradores IA';end if;if not exists(select 1 from public.atenciones_clinicas where id=atencion_id)then raise exception using errcode='P0001',message='Atención no encontrada';end if;select coalesce(jsonb_agg(public.borrador_ia_json(d)order by d.generado_en desc),'[]'::jsonb)into result from public.borradores_ia d where d.atencion_id=listar_borradores_ia.atencion_id;return result;end $$;
create or replace function public.contexto_copiloto(atencion_id bigint,tipo text)returns jsonb language plpgsql stable security definer set search_path=''as $$declare result jsonb;begin if not public.has_permission('IA_ESCRIBIR')then raise exception using errcode='42501',message='No autorizado para generar borradores';end if;if tipo not in('RESUMEN_HISTORIA','BORRADOR_EVOLUCION','INDICACIONES_POSTCONSULTA','VERIFICACION_CIERRE','PLAN_TRATAMIENTO','ALERTAS_CLINICAS','RESUMEN_PARA_PACIENTE')then raise exception using errcode='P0001',message='Tipo de borrador inválido';end if;select jsonb_build_object('encounter',public.atencion_json(a),'encounterVersion',a.version,'patient',jsonb_build_object('id',p.id,'historyNumber',p.numero_historia,'name',concat_ws(' ',p.nombres,p.apellido_paterno,p.apellido_materno),'birthDate',p.fecha_nacimiento),'histories',coalesce((select jsonb_agg(jsonb_build_object('type',h.tipo,'description',h.descripcion))from public.paciente_antecedentes h where h.paciente_id=p.id and h.activo),'[]'::jsonb),'allergies',coalesce((select jsonb_agg(jsonb_build_object('substance',x.sustancia,'reaction',x.reaccion,'severity',x.severidad))from public.paciente_alergias x where x.paciente_id=p.id and x.activo),'[]'::jsonb),'medications',coalesce((select jsonb_agg(jsonb_build_object('medication',m.medicamento,'dose',m.dosis))from public.paciente_medicamentos m where m.paciente_id=p.id and m.activo and m.vigente),'[]'::jsonb),'type',tipo)into result from public.atenciones_clinicas a join public.pacientes p on p.id=a.paciente_id where a.id=atencion_id;if result is null then raise exception using errcode='P0001',message='Atención no encontrada';end if;return result;end $$;
create or replace function public.crear_borrador_ia(atencion_id bigint,tipo text,contenido text,datos_fuente jsonb,campos_faltantes jsonb)returns jsonb language plpgsql security definer set search_path=''as $$declare actor bigint:=public.current_app_user_id();item public.borradores_ia;patient_id bigint;begin if actor is null or not public.has_permission('IA_ESCRIBIR')then raise exception using errcode='42501',message='No autorizado para generar borradores';end if;select paciente_id into patient_id from public.atenciones_clinicas where id=atencion_id;if patient_id is null then raise exception using errcode='P0001',message='Atención no encontrada';end if;if coalesce((datos_fuente->>'atencionVersion')::bigint,-1)<>(select version from public.atenciones_clinicas where id=atencion_id)then raise exception using errcode='P0001',message='La atención cambió durante la generación';end if;insert into public.borradores_ia(atencion_id,paciente_id,tipo,contenido,datos_fuente,campos_faltantes,advertencia,generado_por)values(atencion_id,patient_id,tipo,btrim(contenido),datos_fuente,coalesce(campos_faltantes,'[]'::jsonb),'Contenido preparado como borrador. No constituye diagnóstico ni reemplaza el criterio del odontólogo.',actor)returning*into item;perform public.registrar_auditoria('GENERAR_BORRADOR_IA','BORRADOR_IA',item.id::text,tipo);return public.borrador_ia_json(item);end $$;
create or replace function public.revisar_borrador_ia(borrador_id bigint,accion text,version_actual bigint,valor text default null)returns jsonb language plpgsql security definer set search_path=''as $$declare actor bigint:=public.current_app_user_id();item public.borradores_ia;current_version bigint;begin if actor is null or not public.has_permission('IA_APROBAR')or not exists(select 1 from public.usuarios_roles ur join public.roles r on r.id=ur.rol_id where ur.usuario_id=actor and r.codigo='ODONTOLOGO'and r.activo)then raise exception using errcode='42501',message='La revisión requiere un odontólogo activo';end if;select*into item from public.borradores_ia where id=borrador_id for update;if not found then raise exception using errcode='P0001',message='Borrador no encontrado';end if;if item.version<>version_actual then raise exception using errcode='P0001',message='El borrador fue actualizado por otro usuario';end if;select version into current_version from public.atenciones_clinicas where id=item.atencion_id;if coalesce((item.datos_fuente->>'atencionVersion')::bigint,-1)<>current_version then raise exception using errcode='P0001',message='La atención cambió desde que se generó el borrador. Genere uno nuevo y revíselo';end if;if item.estado<>'BORRADOR'then raise exception using errcode='P0001',message='El borrador ya fue revisado';end if;if accion='EDITAR'then if nullif(btrim(valor),'')is null then raise exception using errcode='P0001',message='El contenido es obligatorio';end if;update public.borradores_ia set contenido=btrim(valor),version=version+1 where id=borrador_id returning*into item;elsif accion='APROBAR'then update public.borradores_ia set estado='APROBADO',revisado_por=actor,revisado_en=now(),version=version+1 where id=borrador_id returning*into item;elsif accion='RECHAZAR'then if nullif(btrim(valor),'')is null then raise exception using errcode='P0001',message='Indique el motivo del rechazo';end if;update public.borradores_ia set estado='RECHAZADO',motivo_rechazo=btrim(valor),revisado_por=actor,revisado_en=now(),version=version+1 where id=borrador_id returning*into item;else raise exception using errcode='P0001',message='Acción de revisión inválida';end if;perform public.registrar_auditoria(accion||'_BORRADOR_IA','BORRADOR_IA',item.id::text,item.tipo);return public.borrador_ia_json(item);end $$;

revoke all on function public.borrador_ia_json(public.borradores_ia),public.listar_borradores_ia(bigint),public.contexto_copiloto(bigint,text),public.crear_borrador_ia(bigint,text,text,jsonb,jsonb),public.revisar_borrador_ia(bigint,text,bigint,text)from public;
grant execute on function public.listar_borradores_ia(bigint),public.contexto_copiloto(bigint,text),public.crear_borrador_ia(bigint,text,text,jsonb,jsonb),public.revisar_borrador_ia(bigint,text,bigint,text)to authenticated;
